/*
  Extraordinary CV theme — drop-in for your current HTML
  Works with: <main class="cv">, .cv__header, .cv__contact-grid, section, article

  IMPORTANT (GitHub Pages):
  - Keep only: <link rel="stylesheet" href="styles.css" />
*/

:root{
  color-scheme: dark;

  /* Palette */
  --bg:#0b1220;
  --card:rgba(255,255,255,0.04);
  --card-strong:rgba(255,255,255,0.06);
  --border:rgba(255,255,255,0.10);
  --text:#e9edf5;
  --muted:#98a4c0;
  --soft:rgba(255,255,255,0.12);

  --accent:#37d0b3;
  --accent-2:#f7c948;

  --max: 1100px;
  --r: 16px;
  --r2: 20px;
  --shadow: 0 18px 50px rgba(0,0,0,.55);
  --shadow2: 0 10px 30px rgba(0,0,0,.45);
  --ring: 0 0 0 3px rgba(55,208,179,.25);
}

/* Inline from Universal.css (was previously linked locally) */
u{
  color:#2100fd;
  text-decoration:none;
  font-weight:bold;
  font-style:normal;
}

b{
  color:#fd0054;
  text-decoration:none;
  font-weight:bold;
  font-style:normal;
}

em{
  text-decoration:none;
  font-weight:bold;
  font-style:normal;
  color:#08cca2;
}

strong{
  color:#09a8cc;
  font-weight:bold;
  font-style:normal;
  text-decoration:none;
}

.xs_indent_para{
  padding-left:10pt;
  text-indent:0pt;
  line-height:100%;
  text-align:left;
}

.s_indent_para{
  padding-left:16pt;
  text-indent:0pt;
  line-height:100%;
  text-align:left;
}

.regular_para{
  padding-left:28pt;
  text-indent:0pt;
  line-height:100%;
  text-align:left;
}

.l_indent_para{
  padding-left:37pt;
  text-indent:0pt;
  line-height:100%;
  text-align:left;
}

.xxxxl_indent_para{
  padding-left:55pt;
  text-indent:0pt;
  line-height:100%;
  text-align:left;
}

*{ box-sizing:border-box; }
html,body{ height:100%; }
html{ scroll-behavior: smooth; }

body{
  margin:0;
  padding: 28px 16px;
  font-family: 'Manrope', system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  color: var(--text);
  line-height: 1.7;
  letter-spacing: .06px;
  background:
    radial-gradient(circle at 20% 20%, rgba(55,208,179,0.14), transparent 28%),
    radial-gradient(circle at 80% 10%, rgba(247,201,72,0.16), transparent 26%),
    radial-gradient(circle at 60% 90%, rgba(55,208,179,0.08), transparent 24%),
    var(--bg);
}

/* Subtle texture without images */
body::before{
  content:"";
  position:fixed;
  inset:0;
  pointer-events:none;
  opacity:.16;
  background:
    repeating-linear-gradient(0deg, rgba(255,255,255,.02) 0 1px, transparent 1px 3px),
    repeating-linear-gradient(90deg, rgba(255,255,255,.015) 0 1px, transparent 1px 4px);
  mix-blend-mode: overlay;
}

a{ color: var(--accent); text-decoration:none; }
a:hover{ text-decoration: underline; }
a:focus{ outline:none; box-shadow: var(--ring); border-radius: 10px; }

/* Main card */
.cv{
  max-width: var(--max);
  margin: 0 auto;
  border-radius: 26px;
  border: 1px solid rgba(255,255,255,0.08);
  background: rgba(8,12,20,0.8);
  backdrop-filter: blur(6px);
  box-shadow: var(--shadow);
}

.cv__layout{
  display:grid;
  grid-template-columns: 180px 1fr;
  gap: 22px;
  align-items:start;
  padding: 0 18px 24px;
  position: relative;
}

.cv__toc{
  position: sticky;
  top: 18px;
  align-self: start;
  padding: 12px 12px;
  border-radius: var(--r2);
  border: 1px solid var(--border);
  background: linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
  backdrop-filter: blur(1rem);
  box-shadow: var(--shadow2);
  z-index: 50;
}

.cv__toc strong{
  font-size: 16px;
  text-align: center;
  letter-spacing: .04em;
}

.cv__toc ul{
  list-style:none;
  padding:0;
  margin:10px 0 0 0;
  display:flex;
  flex-direction:column;
  gap:8px;
}

.cv__toc li a{
  color: var(--muted);
  font-weight: 600;
  font-size: 15px;
  text-decoration:none;
  padding: 5px 9px;
  border-radius: 12px;
  display:inline-block;
  transition: color .18s ease, background .18s ease;
}

.cv__toc li a:hover{
  color: var(--accent);
  background: rgba(55,208,179,0.08);
}

.cv__toc li a.is-active{
  color: var(--accent);
  background: rgba(55,208,179,0.14);
  box-shadow: 0 0 0 1px rgba(55,208,179,0.35) inset;
}

/* Hero */
.cv__hero{
  padding: 28px 26px 24px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--r2);
  background:
    radial-gradient(700px 320px at 18% 10%, rgba(55,208,179,0.18), transparent 58%),
    radial-gradient(820px 280px at 75% 0%, rgba(247,201,72,0.16), transparent 60%),
    linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.015));
}

.cv__hero-grid{
  display:grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 22px;
  align-items:start;
}

.cv__hero-text h1{
  margin: 8px 0;
  font-family: 'Sora','Space Grotesk',sans-serif;
  font-weight: 700;
  font-size: clamp(28px, 3.2vw, 42px);
  line-height: 1.05;
  letter-spacing: -.02em;
  background: linear-gradient(90deg, #fdfdfd, rgba(55,208,179,0.92), rgba(247,201,72,0.8));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.chip{
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding:6px 12px;
  border-radius:999px;
  border:1px solid var(--border);
  background: rgba(255,255,255,0.06);
  color: var(--text);
  font-size: 13px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.chip--soft{
  background: rgba(55,208,179,0.14);
  border-color: rgba(55,208,179,0.28);
  color: #d9fff7;
}

.hero-subtitle{
  margin: 10px 0 12px;
  color: var(--muted);
  max-width: 72ch;
}

.hero-highlights{
  list-style: none;
  padding: 0;
  margin: 12px 0 16px;
  display:grid;
  gap: 8px;
}

.hero-highlights li{
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  color: var(--text);
}

.hero-actions{
  display:flex;
  gap: 10px;
  flex-wrap: wrap;
}

.hero-swipe-hint{
  margin-top: 10px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px dashed rgba(55,208,179,0.35);
  background: rgba(55,208,179,0.08);
  color: var(--muted);
  font-size: 13px;
}

.hero-swipe-text{
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.btn{
  display:inline-flex;
  align-items:center;
  gap: 8px;
  border-radius: 14px;
  padding: 10px 14px;
  border: 1px solid rgba(55,208,179,0.35);
  background: rgba(55,208,179,0.14);
  color: var(--text);
  font-size: 14px;
  text-decoration:none;
  transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease, background .16s ease;
}
.btn:hover{ border-color: rgba(55,208,179,0.5); background: rgba(55,208,179,0.2); transform: translateY(-1px); }
.btn-primary{
  background: linear-gradient(135deg, rgba(55,208,179,0.9), rgba(55,208,179,0.7));
  border-color: rgba(55,208,179,0.6);
  color: #03100d;
  font-weight: 700;
  box-shadow: 0 12px 30px rgba(55,208,179,0.25);
}
.btn-ghost{
  border-color: rgba(255,255,255,0.18);
  background: rgba(255,255,255,0.05);
}

.cv__hero-aside{
  display:grid;
  gap: 12px;
}

.hero-card{
  padding: 14px 14px;
  border-radius: var(--r2);
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.04);
  box-shadow: var(--shadow2);
}

.hero-role{
  margin: 6px 0 0;
  font-weight: 600;
  color: #fdfdfd;
}

h1{
  margin:0;
  font-weight: 850;
  font-size: clamp(26px, 3vw, 38px);
  line-height: 1.1;
  letter-spacing: -.02em;
  background: linear-gradient(90deg, rgba(245,247,255,.96), rgba(124,183,255,.90), rgba(167,139,250,.86));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* Contact grid -> premium pills */
.cv__contact-grid{
  display:grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
  margin-top: 12px;
  justify-content: start;
}

.cv__contact-grid > div{
  padding: 12px 12px;
  border-radius: var(--r2);
  border: 1px solid var(--border);
  background:
    linear-gradient(180deg, rgba(255,255,255,.045), rgba(255,255,255,.02));
  box-shadow: 0 10px 22px rgba(0,0,0,.22);
  width: auto;
  max-width: 100%;
}

.cv__contact-grid h3{
  margin:0 0 6px;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: .14em;
  color: var(--muted);
}

.cv__contact-grid p{ margin:0; color: rgba(245,247,255,.88); }
.cv__contact-grid a{
  display: inline;
  overflow-wrap: anywhere;
}

/* Section layout */
section{
  padding: 0 22px;
  margin-top: 16px;
  transition: background-color .18s ease, border-color .18s ease, box-shadow .18s ease;
}

/* h2 becomes a labelled divider */
h2{
  margin: 18px 0 10px;
  font-family: 'Sora','Space Grotesk',sans-serif;
  font-size: 18px;
  text-transform: uppercase;
  letter-spacing: .16em;
  color: rgba(245,247,255,.72);
  display:flex;
  gap: 10px;
  align-items:center;
  scroll-margin-top: 20px;
}

h2::before{
  content:"";
  width: 10px;
  height: 10px;
  border-radius: 3px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  box-shadow: 0 0 0 4px rgba(55,208,179,.16);
}

p{ margin: 8px 0; color: rgba(245,247,255,.90); }
.muted{ color: var(--muted); }

/* Goals + Skills blocks look like cards */
.cv__summary,
.cv__skills,
.media-card{
  padding: 16px 16px;
  border-radius: var(--r2);
  border: 1px solid var(--border);
  background: var(--card);
  box-shadow: var(--shadow2);
  backdrop-filter: blur(10px);
}

/* Experience cards */
article{
  margin: 12px 0;
  padding: 14px 14px;
  border-radius: var(--r2);
  border: 1px solid var(--border);
  background: var(--card-strong);
  box-shadow: 0 10px 26px rgba(0,0,0,.28);
  transition: transform .14s ease, border-color .14s ease, background .14s ease;
}

article:hover{
  transform: translateY(-2px);
  border-color: rgba(55,208,179,.22);
  background: rgba(255,255,255,0.07);
}

h3{
  margin: 0 0 10px;
  font-family: 'Sora','Space Grotesk',sans-serif;
  font-size: 16px;
}
h4{
  margin: 10px 0 8px;
  font-family: 'Sora','Space Grotesk',sans-serif;
  font-size: 12px;
}
h5{
  margin: 10px 0 6px;
  font-family: 'Sora','Space Grotesk',sans-serif;
  font-size: 14px;
  letter-spacing: .02em;
}

.section--active{
  padding-bottom: 22px;
  margin-top: 16px;
  margin-bottom: 16px;
  background: linear-gradient(180deg, rgba(55,208,179,.12), rgba(55,208,179,.05));
  border-radius: var(--r2);
  border: 1px solid rgba(55,208,179,.32);
  box-shadow: 0 16px 34px rgba(55,208,179,.24);
  animation: sectionHighlight 0.8s cubic-bezier(.19,1,.22,1) forwards;
}

@keyframes sectionHighlight{
  0%{
    background: linear-gradient(180deg, rgba(55,208,179,.24), rgba(55,208,179,.12));
    box-shadow: 0 22px 44px rgba(55,208,179,.30);
    transform: translateY(1px);
  }
  25%{
    background: linear-gradient(180deg, rgba(55,208,179,.20), rgba(55,208,179,.10));
    box-shadow: 0 20px 40px rgba(55,208,179,.26);
    transform: translateY(0);
  }
  50%{
    background: linear-gradient(180deg, rgba(55,208,179,.16), rgba(55,208,179,.08));
    box-shadow: 0 18px 36px rgba(55,208,179,.22);
  }
  75%{
    background: linear-gradient(180deg, rgba(55,208,179,.14), rgba(55,208,179,.06));
    box-shadow: 0 16px 32px rgba(55,208,179,.20);
  }
  100%{
    background: linear-gradient(180deg, rgba(55,208,179,.12), rgba(55,208,179,.05));
    box-shadow: 0 16px 34px rgba(55,208,179,.24);
    transform: translateY(0);
  }
}

/* Lists */
ul{ margin: 8px 0 0 18px; padding:0; }
li{ margin: 4px 0; color: rgba(245,247,255,.88); }
li::marker{ color: rgba(55,208,179,.70); }

/* Fix nested <ul> spacing (you have one inside Technical Skills + GMRRF) */
ul ul{ margin-top: 6px; }

/* Make long lines readable */
.cv p, .cv li{ max-width: 95ch; }

.life-story{
  margin-top: 10px;
  padding: 18px 18px;
  border-radius: var(--r2);
  border: 1px solid var(--border);
  background: linear-gradient(135deg, rgba(255,255,255,0.04), rgba(255,255,255,0.02));
  box-shadow: var(--shadow2);
}
.life-story__header{
  display:flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}
.life-story__controls{
  display:flex;
  align-items:center;
  gap: 10px;
}
.pill-btn{
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.06);
  color: var(--text);
  padding: 8px 12px;
  border-radius: 999px;
  cursor: pointer;
  box-shadow: 0 10px 22px rgba(0,0,0,.22);
  transition: transform .16s ease, border-color .16s ease, background .16s ease;
}
.pill-btn:hover{
  transform: translateY(-1px);
  border-color: rgba(55,208,179,.32);
  background: rgba(55,208,179,0.12);
}
.life-story__dots{
  display:flex;
  gap: 8px;
}
.life-story__dot{
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.14);
  cursor: pointer;
  transition: transform .16s ease, background .16s ease, border-color .16s ease;
}
.life-story__dot.is-active{
  transform: scale(1.2);
  background: rgba(55,208,179,0.8);
  border-color: rgba(55,208,179,0.6);
}
.life-story__carousel{
  margin-top: 12px;
  display:grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 14px;
}
.life-story__slide{
  border-radius: var(--r2);
  padding: 1px;
  background: linear-gradient(135deg, rgba(55,208,179,0.35), rgba(247,201,72,0.28));
  opacity: 0.65;
  transition: opacity .22s ease, transform .22s ease, box-shadow .22s ease;
}
.life-story__slide.is-active{
  opacity: 1;
  transform: translateY(-2px);
  box-shadow: 0 18px 34px rgba(0,0,0,0.38);
}
.life-story__glass{
  height: 100%;
  border-radius: calc(var(--r2) - 2px);
  padding: 16px;
  background: rgba(8,12,20,0.72);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.12);
  display:grid;
  gap: 8px;
}
.life-story__eyebrow{
  letter-spacing: .12em;
  text-transform: uppercase;
  font-size: 12px;
  color: var(--muted);
  margin: 0;
}
.life-story__tag{
  align-self: start;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(55,208,179,0.32);
  background: rgba(55,208,179,0.12);
  color: #d9fff7;
  font-size: 12px;
}

.story-body{
  margin:0;
  padding: 28px 16px 42px;
  font-family: 'Manrope', system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  color: var(--text);
  background:
    radial-gradient(circle at 12% 18%, rgba(55,208,179,0.12), transparent 30%),
    radial-gradient(circle at 84% 16%, rgba(247,201,72,0.14), transparent 32%),
    radial-gradient(circle at 60% 88%, rgba(55,208,179,0.10), transparent 28%),
    var(--bg);
}
.story-shell{
  max-width: 960px;
  margin: 0 auto;
  display: grid;
  gap: 18px;
}
.story-hero{
  padding: 18px 18px;
  border-radius: var(--r2);
  border: 1px solid var(--border);
  background: rgba(8,12,20,0.82);
  box-shadow: var(--shadow);
  display:flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
}
.story-title{
  margin: 6px 0;
  font-family: 'Sora','Space Grotesk',sans-serif;
  font-size: clamp(26px, 3vw, 36px);
  letter-spacing: -.01em;
  background: linear-gradient(90deg, #fdfdfd, rgba(55,208,179,0.92), rgba(247,201,72,0.8));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.story-subtitle{ margin: 6px 0 10px; color: var(--muted); max-width: 62ch; }
.story-actions{
  display:flex;
  gap: 10px;
  flex-wrap: wrap;
}
.story-hero__badge{
  min-width: 120px;
  padding: 12px 14px;
  border-radius: var(--r2);
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.05);
  text-align: center;
  box-shadow: var(--shadow2);
}
.chapter-card{
  border-radius: var(--r2);
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.04);
  box-shadow: var(--shadow2);
  padding: 16px;
}
.chapter-card__header{
  display:flex;
  justify-content: space-between;
  gap: 12px;
  align-items:center;
  flex-wrap: wrap;
}
.chapter-controls{
  display:flex;
  align-items:center;
  gap: 10px;
}
.chapter-dots{
  display:flex;
  gap: 8px;
}
.chapter-dots button{
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.14);
  cursor:pointer;
  transition: transform .16s ease, background .16s ease, border-color .16s ease;
}
.chapter-dots button.is-active{
  transform: scale(1.2);
  background: rgba(55,208,179,0.8);
  border-color: rgba(55,208,179,0.6);
}
.chapter-viewport{
  position: relative;
  overflow: hidden;
  margin-top: 14px;
  min-height: 320px;
}
.chapter-stack{
  display: grid;
  gap: 12px;
  transition: transform .4s cubic-bezier(.22,.61,.36,1);
}
.chapter{
  padding: 16px 16px;
  border-radius: var(--r2);
  border: 1px solid var(--border);
  background: rgba(8,12,20,0.78);
  box-shadow: 0 12px 28px rgba(0,0,0,0.32);
}
.chapter__header{
  display:flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 10px;
}
.chapter__kicker{
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--muted);
  font-size: 12px;
  margin:0;
}
.chapter__title{ margin: 6px 0 8px; }
.chapter__body p{ margin: 8px 0; }
.chapter__goals{ margin: 10px 0 0 16px; color: rgba(245,247,255,.9); }
.chapter__closing{ color: var(--muted); }

/* Concept map widget (Life Story) */
.inline-link{ text-decoration: underline; text-underline-offset: 3px; }
.concept-map{

  padding: 16px;
  border: 1px solid var(--border, rgba(255,255,255,.12));
  border-radius: 16px;
  background: var(--surface, rgba(255,255,255,.02));
}
.concept-map__title{
  margin: 0 0 4px 0;
  font-family: "Sora", system-ui, sans-serif;
  font-weight: 700;
}
.concept-map__subtitle{ margin: 0 0 12px 0; }

.story-map{
  position: relative;
  height: 260px;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--border, rgba(255,255,255,.12));
  background:
    radial-gradient(1200px 300px at 30% 10%, rgba(124, 58, 237, .12), transparent 55%),
    radial-gradient(900px 260px at 85% 80%, rgba(34, 197, 94, .10), transparent 55%),
    rgba(255,255,255,.01);
  transform-style: preserve-3d;
  transform: perspective(1000px) rotateX(12deg) rotateY(-10deg);
  transition: transform 280ms ease, box-shadow 280ms ease;
  box-shadow: 0 22px 38px rgba(0,0,0,.28);
}
.story-map::before{
  content:"";
  position:absolute;
  inset:0;
  background: linear-gradient(135deg, rgba(255,255,255,.24), rgba(255,255,255,.03));
  opacity:.28;
  backdrop-filter: blur(18px);
  pointer-events:none;
  transition: opacity 240ms ease;
}
.story-map:hover{ transform: perspective(1000px) rotateX(0deg) rotateY(0deg); }
.story-map--active{ box-shadow: 0 26px 48px rgba(0,0,0,.42); }
.story-map--active::before{ opacity:.52; }

.story-map__lines{ position: absolute; inset: 0; width: 100%; height: 100%; }
.story-map__lines line{
  stroke: var(--muted, #9aa4b2);
  stroke-width: 2;
  opacity: .35;
  filter: drop-shadow(0 6px 10px rgba(0,0,0,.25));
  transition: opacity 220ms ease;
}
.story-map--active .story-map__lines line{ opacity:.9; }

.map-node{
  position: absolute;
  transform: translate(-50%, -50%) translateZ(28px);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 999px;
  border: 1px solid var(--border, rgba(255,255,255,.14));
  background: rgba(15, 20, 29, .55);
  backdrop-filter: blur(8px);
  text-decoration: none;
  font-weight: 600;
  box-shadow: 0 10px 22px rgba(0,0,0,.28);
  transition: transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease, opacity 220ms ease;
  will-change: transform;
  opacity: .6;
}
.map-node:hover{
  transform: translate(-50%, -50%) translateZ(42px);
  border-color: rgba(124, 58, 237, .55);
}
.map-node--core{
  background: rgba(124, 58, 237, .18);
  border-color: rgba(124, 58, 237, .45);
}
.map-node:focus-visible{ outline: 3px solid rgba(124, 58, 237, .55); outline-offset: 3px; }
.map-node--lit{ opacity: 1; }

.mini-link{ margin-top: 12px; }
.cv__summary{ transition: opacity 220ms ease; }
.cv__summary--dim{ opacity: .65; }
.cv__content{
  backdrop-filter: blur(10px);
  border-radius: var(--r2);
  position: relative;
  transition: opacity 200ms ease, filter 200ms ease;
}
.cv__content.is-blocked{ pointer-events: auto; }
.cv__content.is-blocked::after{
  content:"";
  position:absolute;
  inset:0;
  background: rgba(8, 12, 18, 0.82);
  backdrop-filter: blur(10px);
  border-radius: inherit;
  z-index: 5;
}

.map-floater{
  position: absolute;
  top: 200px;
  left: -12px;
  width: 340px;
  max-width: 38vw;
  border-radius: var(--r2);
  z-index: 0;
  pointer-events: auto;
  opacity: .28;
  transition: opacity 200ms ease;
}
.map-floater:hover,
.map-active .map-floater{ opacity: .85; }
.map-floater.is-top{
  z-index: 100;
  opacity: 1;
  background: rgba(255,255,255,.05);
  backdrop-filter: blur(1rem);
}

.map-connector{
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 4;
  opacity: 0.85;
  mix-blend-mode: screen;
  transition:
    opacity 220ms ease,
    filter 220ms ease,
    transform 220ms ease;
}
.map-connector.is-top{
  z-index: 7;
  opacity: 1;
  filter:
    drop-shadow(0 0 14px rgba(1, 0, 2, 0.95))
    drop-shadow(0 0 26px rgba(0, 39, 34, 0.9));
}
.map-connector path{
  stroke: url(#map-connector-grad);
  stroke-width: 3.4;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: .9;
  filter: drop-shadow(0 10px 22px rgba(0,0,0,.32));
  transition:
    stroke 200ms ease,
    opacity 200ms ease,
    stroke-width 200ms ease,
    filter 200ms ease;
}
.map-connector path.glow{
  stroke: rgba(56, 189, 248, 0.8);
  stroke-width: 3.1;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter:
    drop-shadow(0 10px 18px rgba(0,0,0,.32))
    drop-shadow(0 0 12px rgba(56, 189, 248, 0.45));
  opacity: .9;
  transition:
    stroke 200ms ease,
    opacity 200ms ease,
    stroke-width 200ms ease;
}
.map-active .map-connector path{
  opacity: 1;
  stroke-width: 3.4;
}
.map-anchor{
  color: var(--accent);
  font-weight: bold;
  position: relative;
  display: inline-block;
  padding: 2px 4px;
  border-radius: 12px;
  border: 1px solid rgba(124, 58, 237, 0.32);
  box-shadow:
    0 10px 22px rgba(0,0,0,.25),
    0 0 0 8px rgba(124, 58, 237, 0.06);
  z-index: 12;
}

/* Respect reduced motion */
@media (prefers-reduced-motion: reduce){
  *{ transition:none !important; scroll-behavior:auto !important; }
}

@media (max-width: 900px){
  .cv__layout{
    grid-template-columns: 1fr;
  }
  .cv__toc{
    backdrop-filter: blur(10px);
    position: sticky;
    top: 10px;
    order: -1;
    display:flex;
    flex-wrap: wrap;
    gap: 8px;
  }
  .cv__hero-grid{
    grid-template-columns: 1fr;
  }
}

/* Print cleanly */
@media print{
  body{ background: #fff; color:#111; padding:0; }
  body::before{ display:none; }
  .cv{ max-width:none; border: 1px solid #ddd; box-shadow:none; background:#fff; }
  .cv__header{ background:#fff; border-bottom:1px solid #ddd; }
  h1{ color:#111; -webkit-text-fill-color:#111; background:none; }
  a{ color:#111; text-decoration:none; }
  article,.cv__summary,.cv__skills{ box-shadow:none; background:#fff; border-color:#ddd; }
  h2{ color:#111; }
  h2::before{ box-shadow:none; }
}

.inline-image-card {
  position: relative;
}
.inline-image-card img {
  cursor: zoom-in;
}
.inline-image-card .hover-hint {
  position: absolute;
  left: 50%;
  bottom: 12px;
  transform: translateX(-50%);
  background: rgba(10, 14, 22, 0.86);
  color: #e8ecf5;
  padding: 6px 12px;
  border-radius: 999px;
  border: 1px solid var(--border);
  font-size: 13px;
  letter-spacing: 0.2px;
  opacity: 0;
  transition: opacity 0.18s ease;
  pointer-events: none;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.25);
}
.inline-image-card:hover .hover-hint {
  opacity: 1;
}
.image-lightbox {
  position: fixed;
  inset: 0;
  background: rgba(4, 6, 10, 0.86);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 24px;
}
.image-lightbox__img {
  max-width: 90vw;
  max-height: 90vh;
  border-radius: 16px;
  border: 1px solid var(--border);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35);
}
.image-lightbox__close {
  position: absolute;
  top: 16px;
  right: 16px;
  background: rgba(17, 21, 29, 0.9);
  color: #e8ecf5;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 6px 12px;
  font-size: 13px;
  cursor: pointer;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

.media-card .video-frame{
  position: relative;
  border-radius: 14px;
  overflow: hidden;
  border: 1px solid var(--border);
  background: #0f141d;
  min-height: 200px;
}
.video-cover{
  width: 100%;
  height: 100%;
  min-height: 240px;
  display: grid;
  align-items: stretch;
  border: none;
  background:
    linear-gradient(135deg, rgba(55,208,179,0.12), rgba(55,208,179,0)),
    linear-gradient(120deg, rgba(247,201,72,0.12), rgba(247,201,72,0));
  color: var(--text);
  cursor: pointer;
  position: relative;
  padding: 18px;
}
.video-cover__meta{
  align-self: end;
  display: grid;
  gap: 6px;
  text-align: left;
  max-width: 520px;
}
.video-cover__meta strong{
  font-size: 18px;
}
.video-cover__meta small{
  color: var(--muted);
}
.video-cover__play{
  position: absolute;
  right: 18px;
  bottom: 14px;
  font-size: 30px;
  background: rgba(255,255,255,0.08);
  border: 1px solid var(--border);
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  box-shadow: var(--shadow2);
}
.video-embed{
  position: relative;
  padding-bottom: 56.25%;
  height: 0;
  overflow: hidden;
}
.video-embed iframe{
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: 0;
}




